### Objective
Build a production-grade Live Stock Portfolio and Market Watcher demonstrating Riverpod 2.x architecture using ProviderScope, NotifierProvider for synchronous state, AsyncNotifierProvider for asynchronous feeds, ref.watch, ref.read, ref.listen for side-effects, ref.select for surgical rebuilds, and ref.invalidate for pull-to-refresh.

```dart
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

void main() {
  // Riverpod requires wrapping the root application in ProviderScope!
  runApp(
    const ProviderScope(
      child: StockPortfolioApp(),
    ),
  );
}

/// Root application entrypoint.
class StockPortfolioApp extends StatelessWidget {
  const StockPortfolioApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Riverpod 2.x Portfolio Master',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.teal,
        useMaterial3: true,
      ),
      home: const PortfolioDashboardScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. IMMUTABLE DOMAIN MODELS
// ─────────────────────────────────────────────────────────────────────────────

@immutable
class StockPosition {
  final String symbol;
  final String companyName;
  final double currentPrice;
  final double purchasePrice;
  final int shares;

  const StockPosition({
    required this.symbol,
    required this.companyName,
    required this.currentPrice,
    required this.purchasePrice,
    required this.shares,
  });

  double get totalValue => currentPrice * shares;
  double get totalCost => purchasePrice * shares;
  double get unrealizedGain => totalValue - totalCost;
  double get returnPercentage => totalCost == 0 ? 0.0 : (unrealizedGain / totalCost) * 100;

  StockPosition copyWith({
    double? currentPrice,
    int? shares,
  }) {
    return StockPosition(
      symbol: symbol,
      companyName: companyName,
      currentPrice: currentPrice ?? this.currentPrice,
      purchasePrice: purchasePrice,
      shares: shares ?? this.shares,
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. STATE NOTIFIERS & PROVIDERS
// ─────────────────────────────────────────────────────────────────────────────

/// Synchronous Notifier managing user stock holdings.
class PortfolioNotifier extends Notifier<List<StockPosition>> {
  @override
  List<StockPosition> build() {
    // Initial seeded portfolio state
    return const [
      StockPosition(symbol: 'GOOGL', companyName: 'Alphabet Inc.', currentPrice: 178.50, purchasePrice: 150.00, shares: 25),
      StockPosition(symbol: 'AAPL', companyName: 'Apple Inc.', currentPrice: 224.30, purchasePrice: 195.00, shares: 40),
      StockPosition(symbol: 'NVDA', companyName: 'NVIDIA Corp.', currentPrice: 125.80, purchasePrice: 110.00, shares: 60),
    ];
  }

  void addShares(String symbol, int additionalShares) {
    state = [
      for (final position in state)
        if (position.symbol == symbol)
          position.copyWith(shares: position.shares + additionalShares)
        else
          position,
    ];
  }

  void simulatePriceFluctuation() {
    final random = Random();
    state = [
      for (final position in state)
        position.copyWith(
          currentPrice: position.currentPrice * (1 + (random.nextDouble() * 0.04 - 0.02)),
        ),
    ];
  }
}

/// Global NotifierProvider for the portfolio
final portfolioProvider = NotifierProvider<PortfolioNotifier, List<StockPosition>>(
  PortfolioNotifier.new,
);

/// Computed provider calculating total portfolio valuation
final totalPortfolioValuationProvider = Provider<double>((ref) {
  final positions = ref.watch(portfolioProvider);
  return positions.fold(0.0, (sum, p) => sum + p.totalValue);
});

/// Asynchronous Notifier fetching market analyst headlines
class MarketNewsNotifier extends AsyncNotifier<List<String>> {
  @override
  Future<List<String>> build() async {
    // Simulate remote network latency
    await Future.delayed(const Duration(milliseconds: 1000));
    return [
      'Tech rally continues as semiconductor demand surges.',
      'Central bank maintains benchmark interest rate target.',
      'Cloud infrastructure spending accelerates globally.',
    ];
  }

  Future<void> refreshNews() async {
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(() async {
      await Future.delayed(const Duration(milliseconds: 800));
      return [
        'BREAKING: Cross-platform Flutter adoption surges across Fortune 500.',
        'Market closes at record highs following tech quarterly earnings.',
        'Clean Architecture cited as top priority in mobile engineering.',
      ];
    });
  }
}

/// Global AsyncNotifierProvider for market headlines
final marketNewsProvider = AsyncNotifierProvider<MarketNewsNotifier, List<String>>(
  MarketNewsNotifier.new,
);

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRESENTATION LAYER (ConsumerWidget & Granular Observers)
// ─────────────────────────────────────────────────────────────────────────────

class PortfolioDashboardScreen extends ConsumerWidget {
  const PortfolioDashboardScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // ref.listen: Trigger side-effects like SnackBars without rebuilding the widget!
    ref.listen<double>(totalPortfolioValuationProvider, (previous, current) {
      if (previous != null && current > previous) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Portfolio value increased to \$${current.toStringAsFixed(2)}!'),
            duration: const Duration(seconds: 1),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
    });

    return Scaffold(
      appBar: AppBar(
        title: const Text('Live Capital Portfolio'),
        actions: [
          IconButton(
            icon: const Icon(Icons.show_chart),
            tooltip: 'Simulate Market Shift',
            // ref.read: Access notifier method in callback without rebuilding AppBar
            onPressed: () => ref.read(portfolioProvider.notifier).simulatePriceFluctuation(),
          ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Refresh All Feeds',
            // ref.invalidate: Triggers automatic reload of provider
            onPressed: () => ref.invalidate(marketNewsProvider),
          ),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: () async {
          ref.invalidate(portfolioProvider);
          await ref.read(marketNewsProvider.future);
        },
        child: ListView(
          padding: const EdgeInsets.all(16.0),
          children: const [
            _ValuationSummaryCard(),
            SizedBox(height: 20),
            _HoldingsListSection(),
            SizedBox(height: 20),
            _MarketNewsSection(),
          ],
        ),
      ),
    );
  }
}

/// Header displaying total valuation via computed provider
class _ValuationSummaryCard extends ConsumerWidget {
  const _ValuationSummaryCard();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // ref.watch: Subscribes strictly to computed total double
    final totalValue = ref.watch(totalPortfolioValuationProvider);
    final colorScheme = Theme.of(context).colorScheme;

    return Card(
      elevation: 3,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      color: colorScheme.primaryContainer,
      child: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Net Portfolio Equity',
              style: TextStyle(color: colorScheme.onPrimaryContainer, fontWeight: FontWeight.w600),
            ),
            const SizedBox(height: 8),
            Text(
              '\$${totalValue.toStringAsFixed(2)}',
              style: TextStyle(
                fontSize: 32,
                fontWeight: FontWeight.bold,
                color: colorScheme.onPrimaryContainer,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// Holdings list section with selective position rebuilds
class _HoldingsListSection extends ConsumerWidget {
  const _HoldingsListSection();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final positions = ref.watch(portfolioProvider);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          'Active Holdings (${positions.length})',
          style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 10),
        for (final pos in positions)
          Card(
            margin: const EdgeInsets.only(bottom: 10),
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            child: ListTile(
              title: Text('${pos.companyName} (${pos.symbol})', style: const TextStyle(fontWeight: FontWeight.bold)),
              subtitle: Text('${pos.shares} shares @ \$${pos.currentPrice.toStringAsFixed(2)}'),
              trailing: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text('\$${pos.totalValue.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold)),
                  Text(
                    '${pos.unrealizedGain >= 0 ? '+' : ''}${pos.returnPercentage.toStringAsFixed(1)}%',
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                      color: pos.unrealizedGain >= 0 ? Colors.green : Colors.red,
                    ),
                  ),
                ],
              ),
              onTap: () {
                // Buy 5 more shares
                ref.read(portfolioProvider.notifier).addShares(pos.symbol, 5);
              },
            ),
          ),
      ],
    );
  }
}

/// Async news section demonstrating AsyncValue.when pattern matching
class _MarketNewsSection extends ConsumerWidget {
  const _MarketNewsSection();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // ref.watch on AsyncNotifierProvider yields AsyncValue<List<String>>
    final newsAsync = ref.watch(marketNewsProvider);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          'Market Headlines (AsyncNotifier)',
          style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 10),
        newsAsync.when(
          data: (headlines) => Column(
            children: headlines
                .map(
                  (h) => Card(
                    elevation: 1,
                    margin: const EdgeInsets.only(bottom: 8),
                    child: ListTile(
                      leading: const Icon(Icons.newspaper, color: Colors.teal),
                      title: Text(h, style: const TextStyle(fontSize: 13)),
                    ),
                  ),
                )
                .toList(),
          ),
          loading: () => const Center(
            child: Padding(
              padding: EdgeInsets.all(24.0),
              child: CircularProgressIndicator(),
            ),
          ),
          error: (error, stack) => Container(
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: Colors.red.shade50,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Text('News Feed Error: $error', style: const TextStyle(color: Colors.red)),
          ),
        ),
      ],
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Root Configuration with ProviderScope**:
   `ProviderScope` wraps the root application in `main()`. It instantiates the underlying `ProviderContainer`, which stores all state values independently of the widget tree.
2. **NotifierProvider for Synchronous Business Logic**:
   `PortfolioNotifier` subclasses `Notifier<List<StockPosition>>`. State mutations do not call `notifyListeners()`; instead, they assign a new immutable list to `state = [...]`. Subscribing widgets are automatically notified and rebuilt.
3. **AsyncNotifierProvider and AsyncValue**:
   `MarketNewsNotifier` manages asynchronous data fetching. In `_MarketNewsSection`, `ref.watch(marketNewsProvider)` returns an `AsyncValue<List<String>>`. Calling `.when(data: ..., loading: ..., error: ...)` guarantees at compile time that all three async states are safely rendered.
4. **Side-Effects via ref.listen**:
   In `PortfolioDashboardScreen.build`, `ref.listen` watches `totalPortfolioValuationProvider`. When the total valuation increases, it triggers a `SnackBar`. Because `ref.listen` executes purely as a callback, the `PortfolioDashboardScreen` itself is not rebuilt.
5. **ref.invalidate for Declarative Cache Refresh**:
   Tapping the reload icon calls `ref.invalidate(marketNewsProvider)`. Riverpod tears down the existing news state and re-executes `build()`, providing seamless pull-to-refresh integration.
